// Extraer datos del mensaje recibido
const messageText = $json.message?.text ? $json.message.text.trim() : '';
const chatId = $json.message?.chat?.id;

// Separar por espacios en blanco y limpiar el comando si incluye @bot
const parts = messageText.split(/\s+/);
let rawCommand = parts[0] ? parts[0].toLowerCase() : '';
const command = rawCommand.split('@')[0]; // Elimina el username del bot si viniera (/pdcash@MiBot -> /pdcash)

let isCard2Crypto = false;
let isNowPayments = false;
let isPdCash = false;
let isBlink = false;
let isAgent = false;

let baseAmount = null;
let percentage = 0;
let finalAmount = null;
let orderid = '';
let conversationId = null;
let instruction = '';
let errorMessage = '';

if (command === '/card2crypto' || command === '/c2c' || command === '/nowpayments' || command === '/pdcash' || command === '/blink') {
  if (command === '/card2crypto' || command === '/c2c') isCard2Crypto = true;
  if (command === '/nowpayments') isNowPayments = true;
  if (command === '/pdcash') isPdCash = true;
  if (command === '/blink') isBlink = true;

  if (parts.length >= 3) {
    baseAmount = parseFloat(parts[1]);
    percentage = parseFloat(parts[2]);

    // Validar números
    if (isNaN(baseAmount) || baseAmount <= 0) {
      errorMessage = `⚠️ El monto debe ser un número mayor a 0.\nEjemplo: <code>${command} 30 10 ttv0810a</code>`;
    } else if (isNaN(percentage)) {
      errorMessage = `⚠️ El porcentaje debe ser un número válido (ej. 10 o -20).\nEjemplo: <code>${command} 100 -20 ttv0810b</code>`;
    } else {
      // Calcular monto final
      finalAmount = parseFloat((baseAmount * (1 + percentage / 100)).toFixed(2));

      // Asignar u obtener orden opcional
      if (parts.length >= 4 && parts[3].trim() !== '') {
        orderid = parts[3].trim();
      } else {
        const now = new Date();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        const dd = String(now.getDate()).padStart(2, '0');
        orderid = `ttv-${mm}${dd}`;
      }
    }
  } else {
    errorMessage = `⚠️ Sintaxis incompleta para ${command}.\nUso: <code>${command} monto porcentaje [orden]</code>\nEjemplos:\n<code>${command} 24 10 Alvez</code>\n<code>${command} 15 -20 250150</code>`;
  }
} else if (command === '/agent' || command === '/agente') {
  isAgent = true;
  if (parts.length >= 3) {
    const rawConvId = parts[1];
    const convId = parseInt(rawConvId, 10);
    const instructionText = parts.slice(2).join(' ').trim();

    if (isNaN(convId) || convId <= 0) {
      errorMessage = `⚠️ El número de conversación debe ser un valor numérico entero (ej. 1323).\nUso: <code>${command} &lt;id_conversacion&gt; &lt;instruccion&gt;</code>\nEjemplo: <code>${command} 1323 envia instrucciones para instalar en iphone</code>`;
    } else if (!instructionText) {
      errorMessage = `⚠️ Debes indicar la instrucción que el Agente IA debe ejecutar.\nUso: <code>${command} &lt;id_conversacion&gt; &lt;instruccion&gt;</code>\nEjemplo: <code>${command} 1323 envia instrucciones para instalar en iphone</code>`;
    } else {
      conversationId = convId;
      instruction = instructionText;
    }
  } else {
    errorMessage = `⚠️ Sintaxis incompleta para /agent.\nUso: <code>${command} &lt;id_conversacion&gt; &lt;instruccion&gt;</code>\nEjemplo: <code>${command} 1323 envia instrucciones para instalar en iphone</code>`;
  }
}

return {
  json: {
    chatId,
    command,
    isCard2Crypto,
    isNowPayments,
    isPdCash,
    isBlink,
    isAgent,
    conversation_id: conversationId,
    instruction,
    isValid: (isCard2Crypto || isNowPayments || isPdCash || isBlink || isAgent) && !errorMessage,
    baseAmount,
    percentage,
    amount: finalAmount,
    orderid,
    errorMessage,
    rawText: messageText
  }
};

