(() => {
  const link = $json.data?.urls?.payment_page || $json.checkout_url || $json.paylink;
  const baseAmt = $('Parsear y Calcular Comando').item.json.baseAmount;
  const perc = $('Parsear y Calcular Comando').item.json.percentage;
  const finalAmt = $('Parsear y Calcular Comando').item.json.amount;
  const order = $('Parsear y Calcular Comando').item.json.orderid;

  if (link) {
    return '✅ <b>Link de pago PDCash</b>\n\n' +
      '💵 <b>Monto Base:</b> $' + baseAmt + ' USD\n' +
      '📊 <b>Ajuste (%):</b> ' + perc + '%\n' +
      '💰 <b>Monto a Cobrar:</b> $' + finalAmt + ' USD\n' +
      '🆔 <b>Orden:</b> <code>' + order + '</code>\n\n' +
      '🔗 <b>Enlace de Pago:</b>\n' + link;
  } else {
    return '⚠️ <b>Error al generar Link PDCash</b>\n\n' +
      'El servicio externo de pd.cash reportó un error o no responde en este momento (HTTP 500 / Error de pasarela).\n\n' +
      '💵 <b>Monto a Cobrar:</b> $' + finalAmt + ' USD\n' +
      '🆔 <b>Orden:</b> <code>' + order + '</code>\n\n' +
      '👉 <i>Por favor intenta nuevamente en unos minutos o genera el link con otro método (<code>/nowpayments</code> o <code>/card2crypto</code>).</i>';
  }
})()
}}

